export const NATURES=[{id:'hardy',name:'Hardi',up:-1,down:-1},{id:'adamant',name:'Rigide',up:1,down:3},{id:'modest',name:'Modeste',up:3,down:1},{id:'jolly',name:'Jovial',up:5,down:3},{id:'timid',name:'Timide',up:5,down:1},{id:'bold',name:'Assuré',up:2,down:1},{id:'calm',name:'Calme',up:4,down:1}];
export const STAT_NAMES=['PV','Attaque','Défense','Atq. spéciale','Déf. spéciale','Vitesse'];
export function profile(state,key){state.training||={};if(!state.training[key])state.training[key]={xp:125,ev:[0,0,0,0,0,0],iv:[15,15,15,15,15,15],nature:'hardy',moves:[],ability:0};const p=state.training[key];p.xp=Math.max(125,Math.min(1000000,Number(p.xp)||125));p.ev=Array.from({length:6},(_,i)=>Math.max(0,Math.min(252,Math.floor(p.ev?.[i]||0))));p.iv=Array.from({length:6},(_,i)=>Math.max(0,Math.min(31,Math.floor(p.iv?.[i]??15))));let remaining=510;p.ev=p.ev.map(v=>{const n=Math.min(v,remaining);remaining-=n;return n});return p}
export const level=p=>Math.min(100,Math.floor(Math.cbrt(p.xp)+1e-7));
export function stats(dex,key,p,forcedLevel){const base=dex[parseInt(key)].stats,L=forcedLevel||level(p),nature=NATURES.find(n=>n.id===p.nature)||NATURES[0];return base.map((b,i)=>{const raw=Math.floor((2*b+p.iv[i]+Math.floor(p.ev[i]/4))*L/100);if(i===0)return raw+L+10;return Math.floor((raw+5)*(i===nature.up?1.1:i===nature.down?.9:1))})}
export function addXP(state,key,amount){if(!state.roster.includes(key))return 0;const p=profile(state,key),before=level(p);p.xp=Math.min(1000000,p.xp+Math.max(0,amount));return level(p)-before}
export function candy(state,key,count=1){if(!Number.isInteger(count)||count<1||count>100||state.candies<count||!state.roster.includes(key))return false;const p=profile(state,key);if(level(p)>=100)return false;state.candies-=count;addXP(state,key,count*100);return true}
export function trainEV(state,key,index){if(!state.roster.includes(key)||!Number.isInteger(index)||index<0||index>5||state.coins<100)return false;const p=profile(state,key),sum=p.ev.reduce((s,n)=>s+n,0),gain=Math.min(10,252-p.ev[index],510-sum);if(gain<=0)return false;state.coins-=100;p.ev[index]+=gain;return true}
export function trainIV(state,key,index){if(!state.roster.includes(key)||!Number.isInteger(index)||index<0||index>5||state.coins<300)return false;const p=profile(state,key);if(p.iv[index]>=31)return false;state.coins-=300;p.iv[index]=Math.min(31,p.iv[index]+1);return true}
export function setNature(state,key,nature){if(!state.roster.includes(key)||state.coins<250||!NATURES.some(n=>n.id===nature))return false;const p=profile(state,key);if(p.nature===nature)return false;state.coins-=250;p.nature=nature;return true}
export function trainedFighter(dex,state,key,item={},forcedLevel){const p=profile(state,key),d=dex[parseInt(key)],s=stats(dex,key,p,forcedLevel),max=Math.round(s[0]*(1+(item.hp||0)));let moves=(p.moves?.length===4?p.moves.map(id=>d.learnset?.find(m=>m.id===id)).filter(Boolean):d.moves);if(moves.length!==4)moves=d.moves;return{key,id:d.id,name:d.name,level:forcedLevel||level(p),types:d.types,max,hp:max,atk:Math.round(s[1]*(1+(item.atk||0))),def:Math.round(s[2]*(1+(item.def||0))),spa:Math.round(s[3]*(1+(item.atk||0))),spd:Math.round(s[4]*(1+(item.def||0))),speed:s[5],regen:item.regen||0,abilityId:d.abilities?.[p.ability]?.id||0,ability:d.abilities?.[p.ability]?.name||'Standard',moves:moves.map(m=>({...m,left:m.pp}))}}
